CREATE TABLE IF NOT EXISTS approval_requests(id CHAR(36) PRIMARY KEY,request_type VARCHAR(60) NOT NULL,resource_type VARCHAR(60) NOT NULL,resource_id CHAR(36) NOT NULL,title VARCHAR(180) NOT NULL,summary VARCHAR(1000) NOT NULL,status VARCHAR(30) NOT NULL,applicant_id CHAR(36) NOT NULL,current_reviewer_id CHAR(36) NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,completed_at TIMESTAMP NULL,INDEX idx_approval_status(status,current_reviewer_id,created_at),INDEX idx_approval_resource(resource_type,resource_id));
CREATE TABLE IF NOT EXISTS approval_steps(id CHAR(36) PRIMARY KEY,approval_id CHAR(36) NOT NULL,sequence_no INT NOT NULL,reviewer_id CHAR(36) NULL,decision VARCHAR(30) NOT NULL DEFAULT 'pending',comment VARCHAR(500) NOT NULL DEFAULT '',decided_at TIMESTAMP NULL,UNIQUE(approval_id,sequence_no),INDEX idx_approval_step_reviewer(reviewer_id,decision));
CREATE TABLE IF NOT EXISTS approval_state_history(id CHAR(36) PRIMARY KEY,approval_id CHAR(36) NOT NULL,from_status VARCHAR(30) NOT NULL,to_status VARCHAR(30) NOT NULL,actor_id CHAR(36) NOT NULL,comment VARCHAR(500) NOT NULL DEFAULT '',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_approval_history(approval_id,created_at));
CREATE TABLE IF NOT EXISTS notifications(id CHAR(36) PRIMARY KEY,user_id CHAR(36) NOT NULL,category VARCHAR(60) NOT NULL,title VARCHAR(180) NOT NULL,content VARCHAR(1000) NOT NULL,resource_type VARCHAR(60) NOT NULL DEFAULT '',resource_id CHAR(36) NOT NULL DEFAULT '',status VARCHAR(20) NOT NULL DEFAULT 'unread',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,read_at TIMESTAMP NULL,INDEX idx_notification_inbox(user_id,status,created_at),INDEX idx_notification_resource(resource_type,resource_id));
CREATE TABLE IF NOT EXISTS reminder_rules(id CHAR(36) PRIMARY KEY,name VARCHAR(120) NOT NULL UNIQUE,category VARCHAR(60) NOT NULL,recipient_role VARCHAR(80) NOT NULL,days_before INT NOT NULL DEFAULT 0,days_after INT NOT NULL DEFAULT 0,enabled BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS reminder_runs(id CHAR(36) PRIMARY KEY,rule_id CHAR(36) NOT NULL,run_key VARCHAR(160) NOT NULL,status VARCHAR(30) NOT NULL,generated_count INT NOT NULL DEFAULT 0,failed_count INT NOT NULL DEFAULT 0,started_at TIMESTAMP NOT NULL,finished_at TIMESTAMP NULL,UNIQUE(rule_id,run_key),INDEX idx_reminder_run(rule_id,started_at));
